python3 -c "
import json
with open('/app/resources/treasury_bulletin_2010_06.json', 'r') as f:
    data = json.load(f)

# Look for any elements with December 2010
def search_for_dec_2010(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            search_for_dec_2010(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            search_for_dec_2010(v, f'{path}[{i}]')
    elif isinstance(obj, str):
        if '2010' in obj and 'Dec' in obj:
            print(f'Found: {path} = {obj}')

search_for_dec_2010(data)
"
